module k_multiple_free(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [15:0] k,\n    input [15:0] arr_0, arr_1, arr_2, arr_3, arr_4, arr_5, arr_6, arr_7,\n    input [15:0] arr_8, arr_9, arr_10, arr_11, arr_12, arr_13, arr_14, arr_15,\n    output reg [4:0] count,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] LOAD         = 4'd1;\n    localparam [3:0] BUBBLE       = 4'd2;\n    localparam [3:0] BUBBLE_DONE  = 4'd3;\n    localparam [3:0] TRAVERSE     = 4'd4;\n    localparam [3:0] MARK         = 4'd5;\n    localparam [3:0] DONE_STATE   = 4'd6;\n\n    reg [3:0] state, next_state;\n    reg [15:0] sorted_arr [0:15];\n    reg [7:0] cycle_counter;  \n    reg [3:0] bubble_pass;\n    reg [3:0] bubble_idx;\n    reg swapped;\n    reg [3:0] t_idx;\n    reg [3:0] mark_idx;\n    reg [31:0] target;\n    reg [15:0] excl;  // Use bitmask instead of unpacked array for Icarus compatibility\n\n    integer i;  // Loop variable\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            count <= 5'd0;\n            bubble_pass <= 4'd0;\n            bubble_idx <= 4'd0;\n            swapped <= 1'b0;\n            t_idx <= 4'd0;\n            cycle_counter <= 8'd0;\n            excl <= 16'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                sorted_arr[i] <= 16'd0;\n            end\n        end\n        else begin\n            cycle_counter <= (state != IDLE && state != DONE_STATE) ? cycle_counter + 8'd1 : 8'd0;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load input array\n                        sorted_arr[0] <= arr_0;\n                        sorted_arr[1] <= arr_1;\n                        sorted_arr[2] <= arr_2;\n                        sorted_arr[3] <= arr_3;\n                        sorted_arr[4] <= arr_4;\n                        sorted_arr[5] <= arr_5;\n                        sorted_arr[6] <= arr_6;\n                        sorted_arr[7] <= arr_7;\n                        sorted_arr[8] <= arr_8;\n                        sorted_arr[9] <= arr_9;\n                        sorted_arr[10] <= arr_10;\n                        sorted_arr[11] <= arr_11;\n                        sorted_arr[12] <= arr_12;\n                        sorted_arr[13] <= arr_13;\n                        sorted_arr[14] <= arr_14;\n                        sorted_arr[15] <= arr_15;\n                        state <= LOAD;\n                    end\n                end\n                \n                LOAD: begin\n                    // Initialize for bubble sort\n                    bubble_pass <= 4'd0;\n                    bubble_idx <= 4'd0;\n                    swapped <= 1'b0;\n                    state <= BUBBLE;\n                end\n                \n                BUBBLE: begin\n                    if (cycle_counter >= 8'd500) begin\n                        state <= DONE_STATE;\n                    end\n                    else if (bubble_pass < (n - 1)) begin\n                        if (bubble_idx < (n - 1 - bubble_pass)) begin\n                            if (sorted_arr[bubble_idx] > sorted_arr[bubble_idx + 1]) begin\n                                // Swap elements\n                                sorted_arr[bubble_idx] <= sorted_arr[bubble_idx + 1];\n                                sorted_arr[bubble_idx + 1] <= sorted_arr[bubble_idx];\n                                swapped <= 1'b1;\n                            end\n                            bubble_idx <= bubble_idx + 4'd1;\n                        end\n                        else begin\n                            if (swapped) begin\n                                swapped <= 1'b0;\n                                bubble_pass <= bubble_pass + 4'd1;\n                                bubble_idx <= 4'd0;\n                            end\n                            else begin\n                                // Early exit if no swaps\n                                state <= BUBBLE_DONE;\n                            end\n                        end\n                    end\n                    else begin\n                        state <= BUBBLE_DONE;\n                    end\n                end\n                \n                BUBBLE_DONE: begin\n                    // Initialize for traversal\n                    t_idx <= 4'd0;\n                    count <= 5'd0;\n                    excl <= 16'd0;\n                    state <= TRAVERSE;\n                end\n                \n                TRAVERSE: begin\n                    if (cycle_counter >= 8'd500) begin\n                        state <= DONE_STATE;\n                    end\n                    else if (t_idx < n) begin\n                        if (!excl[t_idx]) begin\n                            // Include current element\n                            count <= count + 5'd1;\n                            target <= sorted_arr[t_idx] * k;\n                            mark_idx <= t_idx + 4'd1;\n                            state <= MARK;\n                        end\n                        else begin\n                            t_idx <= t_idx + 4'd1;\n                        end\n                    end\n                    else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                MARK: begin\n                    if (cycle_counter >= 8'd500) begin\n                        state <= DONE_STATE;\n                    end\n                    else if (mark_idx < n) begin\n                        // Check if target is within 16 bits\n                        if (target[31:16] == 16'd0) begin\n                            // Check if current element == target\n                            if (sorted_arr[mark_idx] == target[15:0] && !excl[mark_idx]) begin\n                                excl[mark_idx] <= 1'b1;\n                            end\n                            // Early exit if sorted value exceeds target\n                            if (sorted_arr[mark_idx] > target[15:0]) begin\n                                t_idx <= t_idx + 4'd1;\n                                state <= TRAVERSE;\n                            end\n                            else begin\n                                mark_idx <= mark_idx + 4'd1;\n                            end\n                        end\n                        else begin\n                            // Target exceeds 16 bits, no marking needed\n                            t_idx <= t_idx + 4'd1;\n                            state <= TRAVERSE;\n                        end\n                    end\n                    else begin\n                        t_idx <= t_idx + 4'd1;\n                        state <= TRAVERSE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule